  test('should have accessible name via aria-label', async ({ page }) => {
    const closeButton = page.getByRole('button', { name: 'Close dialog' });
    await expect(closeButton).toBeVisible();
    const ariaLabel = await closeButton.getAttribute('aria-label');
    expect(ariaLabel).toBe('Close dialog');
  });

  test('should have accessible name via title attribute', async ({ page }) => {
    const deleteButton = page.getByRole('button', { name: 'Delete item' });
    await expect(deleteButton).toBeVisible();
    const title = await deleteButton.getAttribute('title');
    expect(title).toBe('Delete item');
  });

  test('should have accessible name via aria-label for settings button', async ({ page }) => {
    const settingsButton = page.getByRole('button', { name: 'Settings' });
    await expect(settingsButton).toBeVisible();
    const ariaLabel = await settingsButton.getAttribute('aria-label');
    expect(ariaLabel).toBe('Settings');
  });

  test('should identify icon buttons without accessible names', async ({ page }) => {
    const buttons = page.getByRole('button');
    const buttonCount = await buttons.count();

    let inaccessibleCount = 0;
    for (let i = 0; i < buttonCount; i++) {
      const button = buttons.nth(i);
      const ariaLabel = await button.getAttribute('aria-label');
      const title = await button.getAttribute('title');
      const textContent = await button.textContent();

      if (!ariaLabel && !title && (!textContent || textContent.trim() === '')) {
        inaccessibleCount++;
      }
    }

    expect(inaccessibleCount).toBe(1);
  });

  test('all icon buttons should have either aria-label or title', async ({ page }) => {
    const buttons = page.getByRole('button');
    const buttonCount = await buttons.count();

    for (let i = 0; i < buttonCount; i++) {
      const button = buttons.nth(i);
      const ariaLabel = await button.getAttribute('aria-label');
      const title = await button.getAttribute('title');
      const textContent = await button.textContent();

      const hasAccessibleName = ariaLabel || title || (textContent && textContent.trim() !== '');

      if (!hasAccessibleName) {
        expect(hasAccessibleName).toBeTruthy();
      }
    }
  });
});
